def root(dep = Depends(p_dep)):
    return {"dep": dep}

client = TestClient(app)

def test_partial_plain_func_custom_string_annotation():
    response = client.get("/")
    print(f"Status code: {response.status_code}")
    print(f"Response: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    test_partial_plain_func_custom_string_annotation()
